import os, base64
base = os.path.dirname(os.path.abspath(__file__))
files_content = {
    "BLUEPRINT.md": "",
    "README.md": "",
    "PENDING.md": "",
    ".env.example": "",
    "docs/section-11-connectors.md": "",
    "docs/section-12-frontend.md": "",
    "docs/appendix-build-kickoff.md": "",
}

for rel_path, b64_data in files_content.items():
    data = base64.b64decode(b64_data).decode('utf-8')
    full_path = os.path.join(base, rel_path.replace("/", os.sep))
    os.makedirs(os.path.dirname(full_path), exist_ok=True)
    with open(full_path, 'w', encoding='utf-8', newline='\n') as out:
        out.write(data)
    print(f"Created {rel_path}")
print("All blueprint files created!")
